head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > setColumnDefaultValue]<br/>Column 의 ID 또는 인덱스값을 사용하여 특정 Column 의 defaultValue 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 defaultValue 속성을 설정하려는 Column 의 ID 값을 설정합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };    

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);      

    // target 생성    
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strGridView = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:dataList ' + strNameSpace + ' id="target1" baseNode="list" repeatNode="map">';        
    strTarget += '<w2:columnInfo>';
    strTarget += '<w2:column id="col1" name="name1" dataType="text"></w2:column>';    
    strTarget += '<w2:column id="col2" name="name2" dataType="text"></w2:column>';    
    strTarget += '<w2:column id="col3" name="name3" dataType="text"></w2:column>';    
    strTarget += '<w2:column id="col4" name="name4" dataType="text"></w2:column>';    
    strTarget += '</w2:columnInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataList>';     

    $p.data.create(strTarget);

    // gridView 생성
    strGridView += '<w2:gridView ' + strNameSpace + ' sortable="true" rowStatusVisible="true" checkAllType="false" id="gridView1" dataList="target1" style="width:550px;height:300px;" ev:onsort="scwin.gridView1_onsort">';
    strGridView += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strGridView += '<w2:header style="" id="header1">';
    strGridView += '<w2:row style="" id="row1">';
    strGridView += '<w2:column width="120" style="" inputType="text" id="column1" value="name1"></w2:column>';    
    strGridView += '<w2:column width="120" style="" inputType="text" id="column2" value="name2"></w2:column>';    
    strGridView += '<w2:column width="120" style="" inputType="text" id="column3" value="name3"></w2:column>';    
    strGridView += '<w2:column width="120" style="" inputType="text" id="column4" value="name4"></w2:column>';    
    strGridView += '</w2:row>';
    strGridView += '</w2:header>';
    strGridView += '<w2:gBody style="" id="gBody1">';
    strGridView += '<w2:row style="" id="row2">';
    strGridView += '<w2:column width="120" style="" id="col1" value=""></w2:column>';    
    strGridView += '<w2:column width="120" style="" id="col2" value=""></w2:column>';    
    strGridView += '<w2:column width="120" style="" id="col3" value=""></w2:column>';    
    strGridView += '<w2:column width="120" style="" id="col4" value=""></w2:column>';    
    strGridView += '</w2:row>';
    strGridView += '</w2:gBody>';
    strGridView += '</w2:gridView>';    

    // gridView 생성
    scwin["gridView1"] = await $p.dynamicCreate(
        "gridView1",
        "gridView",
        strGridView,
        grp_comp
    );    

    // scwin.btn_getAllJSON_onclick();
}   



scwin.btn_getAllJSON_onclick = function (e) {
    let rtn = target1.getAllJSON();
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);
};



scwin.btn_insertRow_onclick = function (e) {

    target1.insertRow();

    scwin.btn_getAllJSON_onclick();
};



scwin.btn_setColumnDefaultValue_onclick = function (e) {
    let colID = par_columnInfo.getText();
    let defaultValue = par_defaultValue.getText();

	target1.setColumnDefaultValue(colID, defaultValue);

    scwin.btn_insertRow_onclick();
};
